#define entity entity_shared_base
#define region_node_pset entity_shared_region_node_pset
#define region_node_pset_iterator entity_shared_region_node_pset_iterator
#include "KS/SRC/entity_shared.h"
#undef region_node_pset_iterator
#undef region_node_pset
#undef entity

struct region_node_tree_node {
  int color;
  region_node_tree_node* parent;
  region_node_tree_node* left;
  region_node_tree_node* right;
  region_node* value;
};

class region_node_pset_iterator {
  region_node_tree_node* node;

  void increment()
  {
    if (node->right != 0)
    {
      node = node->right;
      while (node->left != 0)
        node = node->left;
    }
    else
    {
      region_node_tree_node* parent = node->parent;
      while (node == parent->right)
      {
        node = parent;
        parent = parent->parent;
      }
      if (node->right != parent)
        node = parent;
    }
  }

public:
  region_node_pset_iterator() {}
  region_node_pset_iterator(region_node_tree_node* value) : node(value) {}
  region_node*& operator*() const { return node->value; }
  region_node_pset_iterator& operator++() { increment(); return *this; }
  region_node_pset_iterator operator++(int)
  {
    region_node_pset_iterator result = *this;
    increment();
    return result;
  }
  bool operator!=(const region_node_pset_iterator& other) const
  {
    return node != other.node;
  }
};

class region_node_pset {
  region_node_tree_node* header;
  unsigned int node_count;

public:
  typedef region_node_pset_iterator const_iterator;
  const_iterator begin() const { return const_iterator(header->left); }
  const_iterator end() const { return const_iterator(header); }
};

class entity : public entity_shared_base {
public:
  const region_node_pset& get_regions() const
  {
    return *(const region_node_pset*)((const char*)this + 0x160);
  }
  virtual void force_region(region_node* r);
  virtual void force_current_region();
  virtual void unforce_regions();
  virtual void force_regions(entity* e);
};

// put me into the same region(s) as the given entity
void entity::force_regions( entity* e )
{
#ifndef REGIONCULL
  region_node_pset::const_iterator i;
  for ( i=e->get_regions().begin(); i!=e->get_regions().end(); i++ )
    force_region( *i );
#endif
}
